"use strict";(globalThis.webpackChunkfontend_doc=globalThis.webpackChunkfontend_doc||[]).push([[2197],{2475:(r,n,e)=>{e.r(n),e.d(n,{assets:()=>u,contentTitle:()=>a,default:()=>d,frontMatter:()=>i,metadata:()=>t,toc:()=>c});const t=JSON.parse('{"id":"\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u8bf7\u6c42\u5c01\u88c5","title":"uniapp \u8bf7\u6c42\u5c01\u88c5","description":"1. \u7b80\u6613\u7248\u672c","source":"@site/docs/\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u8bf7\u6c42\u5c01\u88c5.md","sourceDirName":"\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp","slug":"/\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u8bf7\u6c42\u5c01\u88c5","permalink":"/docs/\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u8bf7\u6c42\u5c01\u88c5","draft":false,"unlisted":false,"editUrl":"https://github.com/ddz12123/ddz12123.github.io/tree/main/docs/\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u8bf7\u6c42\u5c01\u88c5.md","tags":[],"version":"current","frontMatter":{},"sidebar":"docs","previous":{"title":"uniapp \u81ea\u5b9a\u4e49 tabbar","permalink":"/docs/\u524d\u7aef\u77e5\u8bc6\u5e93/Uniapp/\u81ea\u5b9a\u4e49tabbar"}}');var s=e(7259),o=e(9087);const i={},a="uniapp \u8bf7\u6c42\u5c01\u88c5",u={},c=[{value:"1. \u7b80\u6613\u7248\u672c",id:"1-\u7b80\u6613\u7248\u672c",level:2},{value:"1.1 utils/request.js",id:"11-utilsrequestjs",level:3},{value:"2. \u4f7f\u7528\u793a\u4f8b",id:"2-\u4f7f\u7528\u793a\u4f8b",level:2},{value:"2.1 \u8bf7\u6c42\u5c01\u88c5",id:"21-\u8bf7\u6c42\u5c01\u88c5",level:3},{value:"2.2 \u5728\u9875\u9762\u4e2d\u4f7f\u7528",id:"22-\u5728\u9875\u9762\u4e2d\u4f7f\u7528",level:3}];function l(r){const n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",pre:"pre",...(0,o.R)(),...r.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"uniapp-\u8bf7\u6c42\u5c01\u88c5",children:"uniapp \u8bf7\u6c42\u5c01\u88c5"})}),"\n",(0,s.jsx)(n.h2,{id:"1-\u7b80\u6613\u7248\u672c",children:"1. \u7b80\u6613\u7248\u672c"}),"\n",(0,s.jsx)(n.h3,{id:"11-utilsrequestjs",children:"1.1 utils/request.js"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-js",metastring:'title="utils/request.js"',children:"// utils/request.js\r\n\r\nconst BASE_URL = import.meta.env.VITE_APP_BASE_URL\r\nimport { TokenKey } from '@/constant/index.ts'\r\n\r\n// \u5237\u65b0\u72b6\u6001\u7ba1\u7406\r\nlet isRefreshing = false\r\nlet requestQueue = [] // \u5b58\u50a8\u7b49\u5f85\u7684\u8bf7\u6c42\r\n\r\n// \u5c01\u88c5\u8bf7\u6c42\u5931\u8d25\u5904\u7406\r\nconst requestFailHandler = err => {\r\n    let errMsg = '\u7f51\u7edc\u5f02\u5e38\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5'\r\n    if (err.errMsg?.includes('timeout')) {\r\n        errMsg = '\u8bf7\u6c42\u8d85\u65f6\uff0c\u8bf7\u68c0\u67e5\u7f51\u7edc'\r\n    } else if (err.errMsg?.includes('cross-domain')) {\r\n        errMsg = '\u8de8\u57df\u9519\u8bef\uff0c\u8bf7\u914d\u7f6e\u8de8\u57df\u767d\u540d\u5355'\r\n    } else if (err.statusCode === 404) {\r\n        errMsg = '\u63a5\u53e3\u5730\u5740\u4e0d\u5b58\u5728'\r\n    } else if (err.statusCode === 500) {\r\n        errMsg = '\u670d\u52a1\u7aef\u5185\u90e8\u9519\u8bef'\r\n    }\r\n    uni.showToast({ title: errMsg, icon: 'none' })\r\n    return Promise.reject(err)\r\n}\r\n\r\n// \u5237\u65b0 token\r\nconst refreshTokenFn = async () => {\r\n  if (isRefreshing) {\r\n    // \u5df2\u7ecf\u5728\u5237\u65b0\uff0c\u8fd4\u56de\u540c\u4e00\u4e2aPromise\r\n    return refreshPromise\r\n  }\r\n  try {\r\n    isRefreshing = true\r\n    const { useUserStore } = await import('@/stores/user')\r\n    const userStore = useUserStore()\r\n    console.log('userStore', userStore)\r\n    refreshPromise = userStore.reFreshTokenHandler()\r\n    const result = await refreshPromise\r\n    return result\r\n  } finally {\r\n    isRefreshing = false\r\n    refreshPromise = null\r\n  }\r\n}\r\n\r\n// \u62e6\u622a\u5668\u914d\u7f6e\r\nconst interceptors = {\r\n    // \u8bf7\u6c42\u62e6\u622a\r\n    request(config) {\r\n        const token = uni.getStorageSync(TokenKey)\r\n        if (token) {\r\n            config.header = {\r\n                ...config.header,\r\n                Authorization: `Bearer ${token}`\r\n            }\r\n        }\r\n        return config\r\n    },\r\n\r\n    // \u54cd\u5e94\u62e6\u622a\r\n    async response(response, config) {\r\n        const { data, statusCode } = response\r\n\r\n        if (statusCode >= 200 && statusCode < 300) {\r\n            // token \u8fc7\u671f\r\n            if (data?.code === 401) {\r\n                // \u5237\u65b0\u81ea\u8eab\u5931\u8d25\uff0c\u5f3a\u5236\u767b\u5f55\r\n                if (config.url.endsWith('/auth/refresh')) {\r\n                  uni.showToast({ title: '\u767b\u5f55\u8fc7\u671f\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55', icon: 'none' })\r\n                  uni.removeStorageSync(TokenKey)\r\n                  uni.redirectTo({\r\n                    url: '/pages/login/login'\r\n                  })\r\n                  return Promise.reject('refresh token failed')\r\n                }\r\n\r\n                // \u4e0d\u5728\u5237\u65b0 \u2192 \u5f00\u59cb\u5237\u65b0\r\n                if (!isRefreshing) {\r\n                  refreshTokenFn()\r\n                    .then(() => {\r\n                      // \u5237\u65b0\u6210\u529f \u2192 \u91cd\u8bd5\u6240\u6709\u961f\u5217\u4e2d\u7684\u8bf7\u6c42\r\n                      requestQueue.forEach(cb => cb())\r\n                      requestQueue = []\r\n                    })\r\n                    .catch(() => {\r\n                      // \u5237\u65b0\u5931\u8d25 \u2192 \u6e05\u7a7a\u961f\u5217\u5e76\u8df3\u767b\u5f55\r\n                      const failedQueue = [...requestQueue]\r\n                      requestQueue = []\r\n\r\n                      // \u6240\u6709\u7b49\u5f85\u7684\u8bf7\u6c42\u90fd\u5931\u8d25\r\n                      failedQueue.forEach(({ reject }) => {\r\n                        reject(new Error('Token\u5237\u65b0\u5931\u8d25,\u8bf7\u91cd\u65b0\u767b\u5f55'))\r\n                      })\r\n\r\n                      uni.showToast({ title: '\u767b\u5f55\u5df2\u8fc7\u671f\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55', icon: 'none' })\r\n                      uni.removeStorageSync(TokenKey)\r\n                      uni.redirectTo({ url: '/pages/login/login' })\r\n                    })\r\n                }\r\n\r\n                // \u8fdb\u5165\u7b49\u5f85\u961f\u5217\r\n                return new Promise((resolve, reject) => {\r\n                  requestQueue.push({\r\n                    resolve: () => resolve(retryRequestFn(config)),\r\n                    reject\r\n                  })\r\n                })\r\n\r\n                uni.showToast({ title: '\u767b\u5f55\u8fc7\u671f\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55', icon: 'none' })\r\n                uni.removeStorageSync(TokenKey)\r\n                setTimeout(() => {\r\n                    uni.redirectTo({\r\n                        url: '/pages/login/login'\r\n                    })\r\n                }, 500)\r\n                return Promise.reject('\u767b\u5f55\u8fc7\u671f\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55')\r\n            }\r\n\r\n            return data\r\n        }\r\n\r\n        // \u975e 200 \u54cd\u5e94\r\n        uni.showToast({ title: data?.msg || '\u8bf7\u6c42\u9519\u8bef', icon: 'none' })\r\n        return Promise.reject(data)\r\n    },\r\n\r\n    // \u9519\u8bef\u62e6\u622a\r\n    error(error) {\r\n        requestFailHandler(error)\r\n    }\r\n}\r\n\r\n// \u8bf7\u6c42\u91cd\u8bd5\r\nfunction retryRequestFn(config) {\r\n    return new Promise((resolve, reject) => {\r\n        const token = uni.getStorageSync(TokenKey)\r\n        uni.request({\r\n            ...config,\r\n            header: {\r\n                ...config.header,\r\n                Authorization: `Bearer ${token}`\r\n            },\r\n            success: res => {\r\n                try {\r\n                    // \u76f4\u63a5\u5904\u7406\u54cd\u5e94\uff0c\u907f\u514d\u518d\u6b21\u8fdb\u5165\u62e6\u622a\u5668\u5faa\u73af\r\n                    if (res.statusCode >= 200 && res.statusCode < 300) {\r\n                        resolve(res.data)\r\n                    } else {\r\n                        // \u5982\u679c\u8fd8\u662f401\uff0c\u8bf4\u660e\u5237\u65b0\u540e\u7684token\u8fd8\u662f\u65e0\u6548\uff0c\u76f4\u63a5\u8df3\u767b\u5f55\r\n                        if (res.data?.code === 401) {\r\n                            uni.showToast({ title: '\u767b\u5f55\u5df2\u8fc7\u671f\uff0c\u8bf7\u91cd\u65b0\u767b\u5f55', icon: 'none' })\r\n                            uni.removeStorageSync(TokenKey)\r\n                            uni.redirectTo({ url: '/pages/login/login' })\r\n                            reject(new Error('Token\u65e0\u6548,\u8bf7\u91cd\u65b0\u767b\u5f55'))\r\n                        } else {\r\n                            uni.showToast({ title: res.data?.msg || '\u8bf7\u6c42\u9519\u8bef', icon: 'none' })\r\n                            reject(res.data)\r\n                        }\r\n                    }\r\n                } catch (err) {\r\n                    reject(err)\r\n                }\r\n            },\r\n            fail: err => {\r\n                requestFailHandler(err)\r\n                reject(err)\r\n            }\r\n        })\r\n    })\r\n}\r\n\r\n// \u901a\u7528\u8bf7\u6c42\u5c01\u88c5\r\nfunction request(options) {\r\n    const config = interceptors.request({\r\n        url: BASE_URL + options.url,\r\n        method: options.method || 'GET',\r\n        data: options.data || {},\r\n        header: options.header || {},\r\n        timeout: options.timeout || 30000\r\n    })\r\n\r\n    return new Promise((resolve, reject) => {\r\n        uni.request({\r\n            ...config,\r\n            success: res => {\r\n                try {\r\n                    const data = interceptors.response(res, config)\r\n                    resolve(data)\r\n                } catch (err) {\r\n                    reject(err)\r\n                }\r\n            },\r\n            fail: err => {\r\n                interceptors.error(err)\r\n                reject(err)\r\n            }\r\n        })\r\n    })\r\n}\r\n\r\n// \u901a\u7528\u6587\u4ef6\u4e0a\u4f20\u5c01\u88c5\r\nfunction upload(options) {\r\n    const config = interceptors.request({\r\n        url: BASE_URL + options.url,\r\n        filePath: options.filePath,\r\n        name: options.name || 'file',\r\n        formData: options.formData || {},\r\n        header: options.header || {},\r\n        timeout: options.timeout || 30000\r\n    })\r\n\r\n    return new Promise((resolve, reject) => {\r\n        uni.uploadFile({\r\n            ...config,\r\n            success: res => {\r\n                try {\r\n                    // \u89e3\u6790\u54cd\u5e94\u6570\u636e\r\n                    const data = res.data ? JSON.parse(res.data) : {}\r\n                    // \u5e94\u7528\u54cd\u5e94\u62e6\u622a\u5668\r\n                    const result = interceptors.response({ ...res, data }, config)\r\n                    resolve(result)\r\n                } catch (err) {\r\n                    reject(err)\r\n                }\r\n            },\r\n            fail: err => {\r\n                interceptors.error(err)\r\n                reject(err)\r\n            }\r\n        })\r\n    })\r\n}\r\n\r\n// \u5e38\u7528 CRUD \u5c01\u88c5\r\nconst http = {\r\n    get(url, params = {}, config = {}) {\r\n        return request({\r\n            url,\r\n            method: 'GET',\r\n            data: params,\r\n            ...config\r\n        })\r\n    },\r\n\r\n    post(url, data = {}, config = {}) {\r\n        return request({\r\n            url,\r\n            method: 'POST',\r\n            data,\r\n            ...config\r\n        })\r\n    },\r\n\r\n    put(url, data = {}, config = {}) {\r\n        return request({\r\n            url,\r\n            method: 'PUT',\r\n            data,\r\n            ...config\r\n        })\r\n    },\r\n\r\n    delete(url, data = {}, config = {}) {\r\n        return request({\r\n            url,\r\n            method: 'DELETE',\r\n            data,\r\n            ...config\r\n        })\r\n    },\r\n\r\n    // \u6587\u4ef6\u4e0a\u4f20\u65b9\u6cd5\r\n    upload(url, filePath, name = 'file', formData = {}, config = {}) {\r\n        return upload({\r\n            url,\r\n            filePath,\r\n            name,\r\n            formData,\r\n            ...config\r\n        })\r\n    }\r\n}\r\n\r\nexport default http\r\n\r\n\n"})}),"\n",(0,s.jsx)(n.h2,{id:"2-\u4f7f\u7528\u793a\u4f8b",children:"2. \u4f7f\u7528\u793a\u4f8b"}),"\n",(0,s.jsx)(n.h3,{id:"21-\u8bf7\u6c42\u5c01\u88c5",children:"2.1 \u8bf7\u6c42\u5c01\u88c5"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-js",metastring:"title='api/user.js'",children:"import http from '@/utils/request.js';\r\n\r\nexport function getUserList(params) {\r\n    return http.get('/user/list', params);\r\n}\r\n\n"})}),"\n",(0,s.jsx)(n.h3,{id:"22-\u5728\u9875\u9762\u4e2d\u4f7f\u7528",children:"2.2 \u5728\u9875\u9762\u4e2d\u4f7f\u7528"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-js",children:"// \u5728\u4efb\u610f\u9875\u9762\u6216\u6a21\u5757\u4e2d\u4f7f\u7528\r\nimport http from '@/utils/request.js';\r\n\r\nasync function loadData() {\r\n  try {\r\n    const res = await http.get('/user/list', { page: 1 });\r\n    console.log('\u7528\u6237\u5217\u8868\uff1a', res);\r\n  } catch (e) {\r\n    console.error('\u8bf7\u6c42\u5931\u8d25\uff1a', e);\r\n  }\r\n}\r\n\n"})})]})}function d(r={}){const{wrapper:n}={...(0,o.R)(),...r.components};return n?(0,s.jsx)(n,{...r,children:(0,s.jsx)(l,{...r})}):l(r)}},9087:(r,n,e)=>{e.d(n,{R:()=>i,x:()=>a});var t=e(6363);const s={},o=t.createContext(s);function i(r){const n=t.useContext(o);return t.useMemo(function(){return"function"==typeof r?r(n):{...n,...r}},[n,r])}function a(r){let n;return n=r.disableParentContext?"function"==typeof r.components?r.components(s):r.components||s:i(r.components),t.createElement(o.Provider,{value:n},r.children)}}}]);